export async function createScene(engine, canvas, BABYLON) {
  var scene = new BABYLON.Scene(engine);

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.07, 1.14, 0.06));
  camera.alpha = 1.8;
  camera.beta = 0.56;
  camera.radius = 20;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.zoomToMouseLocation = true;
  // camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  var ground = BABYLON.MeshBuilder.CreateGround("ground", { width: 60, height: 60 }, scene);
  ground.material = new BABYLON.PBRMaterial("pbr", scene);
  ground.material.albedoColor = new BABYLON.Color3(0.54, 0.54, 0.54);
  ground.material.metallic = 0;
  ground.material.roughness = 0;

  let points = [];
  let road;
  let spheres = [];
  let dashLines = [];

  let roadMaterial = new BABYLON.StandardMaterial("roadMat", scene);
  roadMaterial.diffuseColor = new BABYLON.Color3(0.1, 0.1, 0.1);
  roadMaterial.disableLighting = true;

  let dashMaterial = new BABYLON.StandardMaterial("dashMat", scene);
  dashMaterial.emissiveColor = new BABYLON.Color3(1, 1, 0);

  let sphereMat = new BABYLON.StandardMaterial("sphereMat", scene);
  sphereMat.diffuseColor = new BABYLON.Color3(1, 0.37, 0);
  sphereMat.emissiveColor = new BABYLON.Color3(1, 0.37, 0);

  let box;
  let boxSpeed = 2; // units per second
  let boxDistance = 0;
  let totalPathLength = 0;
  let pathPoints = [];
  let moving = false;

  let speedInput;
  let playPauseButton;

  let ui = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  let resetButton = BABYLON.GUI.Button.CreateSimpleButton("but", "Reset Road");
  resetButton.width = "150px";
  resetButton.height = "40px";
  resetButton.color = "white";
  resetButton.background = "red";
  resetButton.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  resetButton.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  resetButton.left = "10px";
  resetButton.top = "10px";
  ui.addControl(resetButton);

  resetButton.onPointerUpObservable.add(() => {
    points = [];
    if (road) {
      road.dispose();
      road = null;
    }
    spheres.forEach((s) => s.dispose());
    spheres = [];
    dashLines.forEach((l) => l.dispose());
    dashLines = [];
    if (box) {
      box.dispose();
      box = null;
    }
    moving = false;
    boxDistance = 0;
  });

  let speedLabel = new BABYLON.GUI.TextBlock();
  speedLabel.width = "100px";
  speedLabel.height = "40px";
  speedLabel.text = "Speed:";
  speedLabel.color = "white";
  speedLabel.fontSize = 24;
  speedLabel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  speedLabel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  speedLabel.left = "0px";
  speedLabel.top = "60px";
  ui.addControl(speedLabel);

  speedInput = new BABYLON.GUI.InputText();
  speedInput.width = "50px";
  speedInput.height = "40px";
  speedInput.text = boxSpeed.toString();
  speedInput.color = "white";
  speedInput.background = "gray";
  speedInput.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  speedInput.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  speedInput.left = "110px";
  speedInput.top = "60px";
  speedInput.placeholderText = "Speed";
  ui.addControl(speedInput);

  speedInput.onBlurObservable.add(() => {
    let newSpeed = parseFloat(speedInput.text);
    if (!isNaN(newSpeed) && newSpeed > 0) {
      boxSpeed = newSpeed;
    }
  });

  playPauseButton = BABYLON.GUI.Button.CreateSimpleButton("playPause", "Play");
  playPauseButton.width = "150px";
  playPauseButton.height = "40px";
  playPauseButton.color = "white";
  playPauseButton.background = "green";
  playPauseButton.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  playPauseButton.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  playPauseButton.left = "10px";
  playPauseButton.top = "110px";
  ui.addControl(playPauseButton);

  playPauseButton.onPointerUpObservable.add(() => {
    if (moving) {
      moving = false;
      playPauseButton.textBlock.text = "Play";
      playPauseButton.background = "green";
    } else if (box) {
      moving = true;
      playPauseButton.textBlock.text = "Pause";
      playPauseButton.background = "orange";
    }
  });

  let guideText = new BABYLON.GUI.TextBlock();
  guideText.text = "Click on the ground to create the road and press play";
  guideText.color = "black";
  guideText.fontSize = "24px";
  guideText.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
  guideText.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
  ui.addControl(guideText);

  setTimeout(() => {
    ui.removeControl(guideText);
  }, 5000);

  scene.onPointerObservable.add((pointerInfo) => {
    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERPICK) {
      let pickedPoint = pointerInfo.pickInfo.pickedPoint.clone();
      points.push(pickedPoint);

      let sphere = BABYLON.MeshBuilder.CreateSphere("point", { diameter: 0.1 }, scene);
      sphere.position = pickedPoint;
      sphere.material = sphereMat;
      spheres.push(sphere);

      if (points.length >= 2) {
        let curve = BABYLON.Curve3.CreateCatmullRomSpline(points, 20);
        pathPoints = curve.getPoints();

        let leftPath = [];
        let rightPath = [];

        let roadHalfWidth = 0.3;

        for (let i = 0; i < pathPoints.length; i++) {
          let tangent;
          if (i === 0) {
            tangent = pathPoints[i + 1].subtract(pathPoints[i]);
          } else {
            tangent = pathPoints[i].subtract(pathPoints[i - 1]);
          }
          tangent.normalize();

          let up = new BABYLON.Vector3(0, 1, 0);
          let normal = BABYLON.Vector3.Cross(tangent, up);
          normal.normalize();

          let leftPoint = pathPoints[i].add(normal.scale(roadHalfWidth));
          let rightPoint = pathPoints[i].add(normal.scale(-roadHalfWidth));

          leftPath.push(leftPoint);
          rightPath.push(rightPoint);
        }

        let ribbonPaths = [leftPath, rightPath];

        if (road) {
          road.dispose();
        }

        road = BABYLON.MeshBuilder.CreateRibbon("road", { pathArray: ribbonPaths, closeArray: false, closePath: false }, scene);
        road.position.y = 0.01;
        road.material = roadMaterial;

        let dashLength = 0.2;
        let gapLength = 0.2;

        dashLines.forEach((l) => l.dispose());
        dashLines = [];

        let accumulatedDistance = 0;
        let targetDistance = 0;

        for (let i = 1; i < pathPoints.length; i++) {
          let start = pathPoints[i - 1];
          let end = pathPoints[i];
          let segmentVector = end.subtract(start);
          let segmentLength = segmentVector.length();

          while (targetDistance < accumulatedDistance + segmentLength) {
            let distanceInSegment = targetDistance - accumulatedDistance;
            let ratio = distanceInSegment / segmentLength;
            let position = BABYLON.Vector3.Lerp(start, end, ratio);

            let dashEndDistance = targetDistance + dashLength;

            if (dashEndDistance <= accumulatedDistance + segmentLength) {
              let distanceInSegment2 = dashEndDistance - accumulatedDistance;
              let ratio2 = distanceInSegment2 / segmentLength;
              let position2 = BABYLON.Vector3.Lerp(start, end, ratio2);

              let dash = BABYLON.MeshBuilder.CreateLines("dash", { points: [position, position2] }, scene);
              dash.position.y = 0.011;
              dash.color = new BABYLON.Color3(1, 1, 0);
              dash.material = dashMaterial;
              dashLines.push(dash);
            } else {
              if (i < pathPoints.length - 1) break;
            }

            targetDistance += dashLength + gapLength;
          }

          accumulatedDistance += segmentLength;
        }

        if (!box) {
          box = BABYLON.MeshBuilder.CreateBox("box", { size: 0.3 }, scene);
          box.position = pathPoints[0].clone();
          box.position.y = 0.2;
        } else {
          box.position = pathPoints[0].clone();
          box.position.y = 0.2;
        }

        boxDistance = 0;
        totalPathLength = 0;
        for (let i = 1; i < pathPoints.length; i++) {
          totalPathLength += BABYLON.Vector3.Distance(pathPoints[i - 1], pathPoints[i]);
        }
      }
    }
  });

  scene.onBeforeRenderObservable.add(() => {
    if (moving && pathPoints.length >= 2) {
      let deltaTime = engine.getDeltaTime() / 1000;
      boxDistance += boxSpeed * deltaTime;

      if (boxDistance > totalPathLength) {
        moving = false;
        playPauseButton.textBlock.text = "Play";
        playPauseButton.background = "green";
        return;
      }

      let distanceSoFar = 0;
      for (let i = 1; i < pathPoints.length; i++) {
        let segmentStart = pathPoints[i - 1];
        let segmentEnd = pathPoints[i];
        let segmentLength = BABYLON.Vector3.Distance(segmentStart, segmentEnd);

        if (boxDistance <= distanceSoFar + segmentLength) {
          let localDistance = boxDistance - distanceSoFar;
          let ratio = localDistance / segmentLength;

          let position = BABYLON.Vector3.Lerp(segmentStart, segmentEnd, ratio);
          box.position = position.clone();
          box.position.y = 0.2;

          let direction = segmentEnd.subtract(segmentStart).normalize();
          box.rotation.y = Math.atan2(direction.x, direction.z);
          break;
        }

        distanceSoFar += segmentLength;
      }
    }
  });

  return scene;
}
